exec(compile(open(__file__.replace('-finish.py','-author.py')).read(),__file__,'exec'))
add(69,('함수와 편도함수 그래프 대응','Matching a function and its partials'),('교재의 세 곡면 a,b,c 중 원함수 f와 두 편도함수 f_x,f_y를 식별하고 이유를 설명하라.','Identify f, f_x, and f_y among the three source surfaces a,b,c and explain the choices.'),[('c의 x방향 단면에서 증가·감소와 수평접선 위치를 읽으면 b의 값의 부호와0이 일치한다.','Along x-traces of c, increasing/decreasing portions and horizontal tangencies match the signs and zeros of b.'),('c의 y방향 단면에서 같은 검사를 하면 a와 일치한다. 높이의 크기 자체보다 기울기의 부호와0인 위치를 비교해야 한다.','The same test along y-traces of c matches a. Compare slope signs and zero locations rather than surface heights alone.')],same(r'\[c=f,\qquad b=f_x,\qquad a=f_y.\]'))
calc(70,y/(1+x*x*y*y),[x,y]);calc(71,x*x*y**3,[x,y])
for n in[70,71]:
 b.E[n]['statement']['ko']+=' 원함수와 두 편도함수를 함께 비교할 수 있는 그래프를 그려라.';b.E[n]['statement']['en']+=' Graph the function and both partials for comparison.'
add(72,('곡률과 혼합미분의 부호','Signs of curvature and mixed partials'),('4–5번 원본 곡면에서 '+r'\((a)\ f_{xx}(-1,2),\ (b)\ f_{yy}(-1,2),\ (c)\ f_{xy}(1,2),\ (d)\ f_{xy}(-1,2)\)'+'의 부호를 판정하라.','From the source graph of Exercises4–5 determine the signs of '+r'\((a)\ f_{xx}(-1,2),\ (b)\ f_{yy}(-1,2),\ (c)\ f_{xy}(1,2),\ (d)\ f_{xy}(-1,2)\)'+'.'),[('(a) x단면은 위로 굽으므로 양수이다. (b) 해당 점의 y단면은 아래로 굽으므로 음수이다.','(a) The x-trace is concave up, giving a positive sign. (b) The y-trace is concave down, giving a negative sign.'),('(c) x=1에서는 y가 커질수록 양의 x기울기가 더 커진다. (d) x=-1에서는 음의 x기울기가 더 작아진다.','(c) At x=1, the positive x-slope increases with y. (d) At x=-1, the negative x-slope decreases with y.')],same(r'\[(a)>0,\quad(b)<0,\quad(c)>0,\quad(d)<0.\]'),['a','b','c','d'])
add(73,('표의 차분으로 혼합미분 추정','Estimating mixed partials from a table'),('행 x=2.5,3,3.5와 열 y=1.8,2.0,2.2인 함수값 표의 행은 (12.5,10.2,9.3), (18.1,17.5,15.9), (20.0,22.4,26.1)이다. '+r'\(f_x(3,2),f_x(3,2.2),f_{xy}(3,2)\)'+'를 추정하라.','The table rows for x=2.5,3,3.5, with columns y=1.8,2.0,2.2, are (12.5,10.2,9.3), (18.1,17.5,15.9), (20.0,22.4,26.1). Estimate '+r'\(f_x(3,2),f_x(3,2.2),f_{xy}(3,2)\)'+'.'),fs(r'f_x(3,2)\approx\frac{22.4-10.2}{3.5-2.5}=12.2',r'f_x(3,2.2)\approx\frac{26.1-9.3}{1}=16.8,\quad f_x(3,1.8)\approx\frac{20-12.5}{1}=7.5',r'f_{xy}(3,2)\approx\frac{16.8-7.5}{2.2-1.8}=23.25'),same(r'\[12.2,\qquad16.8,\qquad23.25.\]'),check=('혼합미분은 y에 대해서도 중심차분을 써야23.25가 된다. 한쪽차분23과 구별한다.','Use a centered difference in y as well to obtain23.25, rather than the one-sided estimate23.'))
add(74,('등고선 간격과2계 편미분','Contour spacing and second partials'),('교재 등고선은 오른쪽으로10,8,6,4,2로 감소하고 간격은 점차 넓어진다. 표시점 P에서 '+r'\((a)f_x,(b)f_y,(c)f_{xx},(d)f_{xy},(e)f_{yy}\)'+'의 부호를 정하라.','The source contours decrease10,8,6,4,2 toward the right, with increasing spacing. At P determine the signs of '+r'\((a)f_x,(b)f_y,(c)f_{xx},(d)f_{xy},(e)f_{yy}\)'+'.'),[('(a,b) 오른쪽으로 값이 줄고 위쪽으로 값이 늘어 f_x<0,f_y>0이다.','(a,b) Values fall rightward and rise upward, so f_x<0 and f_y>0.'),('(c) 오른쪽으로 간격이 넓어져 음의 x기울기 크기가 작아지므로 f_xx>0이다.','(c) Wider spacing to the right reduces the magnitude of the negative x-slope, giving f_xx>0.'),('(d,e) 위로 갈수록 높은 값의 등고선이 더 가까워져 x기울기는 더 음수이고 y기울기는 더 양수가 된다.','(d,e) Higher-value contours crowd upward, making the x-slope more negative and the y-slope more positive.')],same(r'\[(a)<0,\quad(b)>0,\quad(c)>0,\quad(d)<0,\quad(e)>0.\]'),['a','b','c','d','e'])
add(75,('단면곡선의 벡터 접선','Vector tangents to traces'),('함수 '+r'\(f=4-x^2-2y^2\)'+'와 P=(1,1,1)에 대해 (a) y=1 단면을 매개화하여 접선 기울기 f_x(1,1)=-2를 확인하고 (b) x=1 단면으로 f_y(1,1)=-4를 확인하라.','For '+r'\(f=4-x^2-2y^2\)'+' and P=(1,1,1), (a) parametrize the trace y=1 and verify slope f_x(1,1)=-2; (b) use x=1 to verify f_y(1,1)=-4.'),fs(r'(a)\ \mathbf r_1(t)=(t,1,2-t^2),\quad\mathbf r_1\prime(1)=(1,0,-2),\quad dz/dx=-2',r'(b)\ \mathbf r_2(t)=(1,t,3-2t^2),\quad\mathbf r_2\prime(1)=(0,1,-4),\quad dz/dy=-4'),same(r'\[(a)\ -2;\qquad(b)\ -4.\]'),['a','b'])
add(76,('지수함수와 라플라시안','Exponential function and the Laplacian'),('조건 '+r'\(u=e^{a_1x_1+\cdots+a_nx_n},\ \sum_i a_i^2=1\)'+'에서 '+r'\(\sum_i u_{x_ix_i}=u\)'+'를 보이라.','For '+r'\(u=e^{a_1x_1+\cdots+a_nx_n},\ \sum_i a_i^2=1\)'+' prove '+r'\(\sum_i u_{x_ix_i}=u\)'+'.'),fs(r'u_{x_i}=a_iu,\quad u_{x_ix_i}=a_i^2u',r'\sum_i u_{x_ix_i}=(\sum_i a_i^2)u=u'),same(r'\[\Delta u=u.\]'))
add(77,('파동방정식의 해','Solutions of the wave equation'),('각 함수가 '+r'\(u_{tt}=a^2u_{xx}\)'+'의 해임을 보이라: '+r'\((a)\sin(kx)\sin(akt),\ (b)t/(a^2t^2-x^2),\ (c)(x-at)^6+(x+at)^6,\ (d)\sin(x-at)+\ln(x+at)\)'+'.','Verify '+r'\(u_{tt}=a^2u_{xx}\)'+' for '+r'\((a)\sin(kx)\sin(akt),\ (b)t/(a^2t^2-x^2),\ (c)(x-at)^6+(x+at)^6,\ (d)\sin(x-at)+\ln(x+at)\)'+'.'),fs(r'(a)\ u_{tt}=-a^2k^2u,\quad u_{xx}=-k^2u',r'(b)\ u=\frac1{2a}\left(\frac1{x+at}-\frac1{x-at}\right)')+[('(b,c,d)는 모두 F(x-at)+G(x+at) 꼴이다. 두 번 미분하면 t미분은 각각 a²를 곱하고 x미분은 곱하지 않는다.','Parts(b,c,d) have the form F(x-at)+G(x+at). Two t-derivatives multiply each term by a² compared with two x-derivatives.')]+fs(r'u_{xx}=F\prime\prime(x-at)+G\prime\prime(x+at),\quad u_{tt}=a^2[F\prime\prime(x-at)+G\prime\prime(x+at)]'),('네 함수 모두 정의되고 두 번 미분가능한 영역에서 파동방정식을 만족한다.','All four satisfy the wave equation wherever defined and twice differentiable.'),['a','b','c','d'])
add(78,('라플라스방정식 판정','Testing Laplace’s equation'),('다음 중 '+r'\(u_{xx}+u_{yy}=0\)'+'을 만족하는 함수를 판정하라: '+r'\((a)x^2+y^2,\ (b)x^2-y^2,\ (c)x^3+3xy^2,\ (d)\ln\sqrt{x^2+y^2},\ (e)\sin x\cosh y+\cos x\sinh y,\ (f)e^{-x}\cos y-e^{-y}\cos x\)'+'.','Determine which satisfy '+r'\(u_{xx}+u_{yy}=0\)'+' among '+r'\((a)x^2+y^2,\ (b)x^2-y^2,\ (c)x^3+3xy^2,\ (d)\ln\sqrt{x^2+y^2},\ (e)\sin x\cosh y+\cos x\sinh y,\ (f)e^{-x}\cos y-e^{-y}\cos x\)'+'.'),fs(r'(a)\Delta u=4;\quad(b)\Delta u=0;\quad(c)\Delta u=12x',r'(d)\ u_{xx}=\frac{y^2-x^2}{(x^2+y^2)^2},\quad u_{yy}=-u_{xx}',r'(e)\ u_{xx}=-u,\quad u_{yy}=u;\qquad(f)\ u_{xx}+u_{yy}=0'),('(b),(d),(e),(f)는 해이며 (d)는 원점을 제외한다. (a),(c)는 해가 아니다.','(b),(d),(e),(f) are solutions, with the origin excluded in(d). Parts(a),(c) are not.'),['a','b','c','d','e','f'])
add(79,('역거리 함수의 조화성','Harmonicity of inverse distance'),('함수 '+r'\(u=1/\sqrt{x^2+y^2+z^2}\)'+'가3차원 라플라스방정식을 만족함을 보이라.','Verify the three-dimensional Laplace equation for '+r'\(u=1/\sqrt{x^2+y^2+z^2}\)'+'.'),fs(r'r=\sqrt{x^2+y^2+z^2}>0,\quad u_{xx}=-r^{-3}+3x^2r^{-5}',r'u_{yy}=-r^{-3}+3y^2r^{-5},\quad u_{zz}=-r^{-3}+3z^2r^{-5}',r'\Delta u=-3r^{-3}+3r^2r^{-5}=0'),same(r'\[\Delta u=0\quad((x,y,z)\ne(0,0,0)).\]'))
add(80,('열방정식 확인','Verifying the heat equation'),('함수 '+r'\(u=e^{-\alpha^2k^2t}\sin(kx)\)'+'가 '+r'\(u_t=\alpha^2u_{xx}\)'+'를 만족함을 보이라.','Verify that '+r'\(u=e^{-\alpha^2k^2t}\sin(kx)\)'+' satisfies '+r'\(u_t=\alpha^2u_{xx}\)'+'.'),fs(r'u_t=-\alpha^2k^2e^{-\alpha^2k^2t}\sin(kx)',r'u_{xx}=-k^2e^{-\alpha^2k^2t}\sin(kx)'),same(r'\[u_t=\alpha^2u_{xx}.\]'))
add(81,('가우스 확산해','Gaussian diffusion solution'),('D>0에서 '+r'\(c(x,t)=(4\pi Dt)^{-1/2}e^{-x^2/(4Dt)}\)'+'가 '+r'\(c_t=Dc_{xx}\)'+'를 만족함을 보이라.','For D>0 prove '+r'\(c(x,t)=(4\pi Dt)^{-1/2}e^{-x^2/(4Dt)}\)'+' satisfies '+r'\(c_t=Dc_{xx}\)'+'.'),fs(r'c_t=c\left(-\frac1{2t}+\frac{x^2}{4Dt^2}\right)',r'c_x=-\frac{x}{2Dt}c,\quad c_{xx}=c\left(\frac{x^2}{4D^2t^2}-\frac1{2Dt}\right)'),same(r'\[c_t=Dc_{xx}\quad(t>0).\]'))
add(82,('금속판의 온도 변화','Temperature variation on a plate'),('온도 '+r'\(T=60/(1+x^2+y^2)\)'+'(°C, x,y는m)의 (2,1)에서 (a) x방향, (b) y방향 변화율을 구하라.','For temperature '+r'\(T=60/(1+x^2+y^2)\)'+' in°C, with coordinates in meters, find rates at(2,1) in (a) x and (b) y.'),fs(r'T_x=-\frac{120x}{(1+x^2+y^2)^2},\quad T_y=-\frac{120y}{(1+x^2+y^2)^2}'),same(r'\[(a)\ T_x(2,1)=-20/3\ \mathrm{^{\circ}C/m};\quad(b)\ T_y(2,1)=-10/3\ \mathrm{^{\circ}C/m}.\]'),['a','b'])
add(83,('병렬저항의 민감도','Sensitivity of parallel resistance'),('조건 '+r'\(1/R=1/R_1+1/R_2+1/R_3\)'+'에서 '+r'\(\partial R/\partial R_1\)'+'을 구하라.','Given '+r'\(1/R=1/R_1+1/R_2+1/R_3\)'+' find '+r'\(\partial R/\partial R_1\)'+'.'),fs(r'-R^{-2}R_{R_1}=-R_1^{-2}'),same(r'\[\frac{\partial R}{\partial R_1}=\frac{R^2}{R_1^2}.\]'))
add(84,('이상기체법칙의 편미분 항등식','Partial derivative identities for ideal gas'),('고정 m,R에 대한 '+r'\(PV=mRT\)'+'에서 (a) '+r'\(P_VV_TT_P=-1\)'+'과 (b) '+r'\(TP_TV_T=mR\)'+'를 증명하라. 각 미분에서는 남은 독립상태변수를 고정한다.','For '+r'\(PV=mRT\)'+' with fixed m,R prove (a) '+r'\(P_VV_TT_P=-1\)'+' and (b) '+r'\(TP_TV_T=mR\)'+'; hold the remaining independent state variable fixed in each derivative.'),fs(r'P_V=-mRT/V^2,\quad V_T=mR/P,\quad T_P=V/(mR),\quad P_T=mR/V',r'(a)\ P_VV_TT_P=-mRT/(PV)=-1',r'(b)\ TP_TV_T=m^2R^2T/(PV)=mR'),('두 항등식 모두 이상기체법칙을 다시 대입하면 성립한다.','Both identities follow by substituting the ideal-gas relation back into the products.'),['a','b'])
add(85,('반데르발스 식의 편미분','Partials of the van der Waals equation'),('상수 n,R,a,b에 대해 '+r'\((P+n^2a/V^2)(V-nb)=nRT\)'+'에서 '+r'\(T_P,P_V\)'+'를 구하라.','For constants n,R,a,b and '+r'\((P+n^2a/V^2)(V-nb)=nRT\)'+' find '+r'\(T_P,P_V\)'+'.'),fs(r'T=\frac{(P+n^2a/V^2)(V-nb)}{nR},\quad P=\frac{nRT}{V-nb}-\frac{n^2a}{V^2}'),same(r'\[T_P=\frac{V-nb}{nR},\qquad P_V=-\frac{nRT}{(V-nb)^2}+\frac{2n^2a}{V^3}.\]'))
WT=.6215+.3965*30**.16;WV=.16*(-11.37+.3965*(-15))*30**(-.84)
add(86,('체감온도 변화의 선형추정','Linear estimates for wind chill'),('모형 '+r'\(W=13.12+0.6215T-11.37v^{0.16}+0.3965Tv^{0.16}\)'+'에서 T=-15°C,v=30km/h일 때 실제온도가1°C 낮아지는 경우와 풍속이1km/h 높아지는 경우 각각 체감온도가 얼마나 내려가는지 추정하라.','Using '+r'\(W=13.12+0.6215T-11.37v^{0.16}+0.3965Tv^{0.16}\)'+' at T=-15°C,v=30km/h, estimate the separate drops caused by a1°C temperature decrease and a1km/h wind-speed increase.'),fs(r'W_T=0.6215+0.3965v^{0.16}',r'W_v=0.16(-11.37+0.3965T)v^{-0.84}')+[(f'현재점에서 W_T≈{WT:.5f}, W_v≈{WV:.5f}이다. 각각 ΔT=-1,Δv=1을 곱한다.',f'At the given point W_T≈{WT:.5f}, W_v≈{WV:.5f}. Multiply by ΔT=-1 and Δv=1 respectively.')],(f'온도 감소에 따른 하락 약{WT:.3f}°C; 풍속 증가에 따른 하락 약{-WV:.3f}°C.',f'Approximate drops: {WT:.3f}°C from the temperature change; {-WV:.3f}°C from the wind-speed change.'))
S0=.1091*160**.425*70**.725;Sw=.425*S0/160;Sh=.725*S0/70
add(87,('인체 표면적의 편미분','Partials of a body-area model'),('표면적모형 '+r'\(S=0.1091w^{0.425}h^{0.725}\)'+'(w는lb,h는in,S는ft²)에서 (a) S_w(160,70), (b) S_h(160,70)을 구하고 해석하라.','For '+r'\(S=0.1091w^{0.425}h^{0.725}\)'+' (w inlb,h inin,S inft²), evaluate and interpret (a) S_w(160,70), (b) S_h(160,70).'),fs(r'S_w=0.425S/w,\quad S_h=0.725S/h')+[('다른 치수를 고정할 때 단위 무게와 단위 높이 증가당 표면적이 늘어나는 비율이다.','They give the increase in area per unit weight or height while the other measurement remains fixed.')],(f'(a) {Sw:.5f}ft²/lb; (b) {Sh:.5f}ft²/in.',f'(a) {Sw:.5f}ft²/lb; (b) {Sh:.5f}ft²/in.'),['a','b'])
add(88,('혈류저항의 변수 의존성','Dependence of blood-flow resistance'),('모형 '+r'\(R=CL/r^4\)'+'에서 L,r에 대한 편미분을 구하고 의미를 설명하라(C>0).','For '+r'\(R=CL/r^4\)'+' find and interpret the partials with respect to L and r, where C>0.'),fs(r'R_L=C/r^4,\quad R_r=-4CL/r^5')+[('반지름을 고정하면 길이가 증가할수록 저항이 증가한다. 길이를 고정하면 반지름 증가가 저항을 감소시킨다.','At fixed radius, increasing length raises resistance. At fixed length, increasing radius lowers it.')],same(r'\[R_L=C/r^4>0,\qquad R_r=-4CL/r^5<0\quad(L,r>0).\]'))
add(89,('비행동력 모형의 편미분','Partials of a flight-power model'),('모형 '+r'\(P(v,x,m)=Av^3+B(mg/x)^2/v\)'+'에서 P_v,P_x,P_m을 구하고 의미를 설명하라. A,B는 종에 따른 상수, g는 중력가속도, x는 날갯짓 시간비율이다.','For '+r'\(P(v,x,m)=Av^3+B(mg/x)^2/v\)'+' find and interpret P_v,P_x,P_m. A,B are species constants, g is gravitational acceleration, and x is the flapping-time fraction.'),fs(r'P=Av^3+\frac{Bm^2g^2}{x^2v}',r'P_v=3Av^2-\frac{Bm^2g^2}{x^2v^2},\quad P_x=-\frac{2Bm^2g^2}{x^3v},\quad P_m=\frac{2Bmg^2}{x^2v}')+[('각 값은 나머지 변수를 고정한 속도·날갯짓비율·질량당 동력 변화이다. 양의 매개변수에서 P_x<0,P_m>0이며 P_v의 부호는 두 항의 경쟁에 달린다.','These are power changes per speed, flapping fraction, and mass with other variables fixed. For positive parameters, P_x<0 and P_m>0; the sign of P_v depends on the competing terms.')],same(r'\[P_v=3Av^2-\frac{Bm^2g^2}{x^2v^2},\quad P_x=-\frac{2Bm^2g^2}{x^3v},\quad P_m=\frac{2Bmg^2}{x^2v}.\]'))
add(90,('지중 온도의 위상지연','Phase lag of underground temperature'),('모형 '+r'\(T=T_0+T_1e^{-\lambda x}\sin(\omega t-\lambda x),\ \omega=2\pi/365,\lambda>0\)'+'에 대해 (a) T_x와 의미, (b) T_t와 의미, (c) T_t=kT_xx의 k, (d) λ=0.2,T₀=0,T₁=10의 그래프, (e) 위상항 -λx의 의미를 구하라(x는ft,t는day).','For '+r'\(T=T_0+T_1e^{-\lambda x}\sin(\omega t-\lambda x),\ \omega=2\pi/365,\lambda>0\)'+' find (a) T_x and its meaning; (b) T_t and its meaning; (c) k in T_t=kT_xx; (d) graph λ=0.2,T₀=0,T₁=10; (e) interpret the phase term -λx (x infeet,t indays).'),fs(r'\psi=\omega t-\lambda x',r'(a)\ T_x=-\lambda T_1e^{-\lambda x}(\sin\psi+\cos\psi)',r'(b)\ T_t=\omega T_1e^{-\lambda x}\cos\psi',r'(c)\ T_{xx}=2\lambda^2T_1e^{-\lambda x}\cos\psi,\quad k=\omega/(2\lambda^2)')+[('(a)는 같은 시각의 깊이당 온도 변화, (b)는 같은 깊이의 시간당 변화이다. (e) 깊이x의 계절변화는 지표보다 λx/ω일 늦고 진폭은 e^{-λx}배로 줄어든다.','Part(a) measures temperature change per depth at fixed time; part(b) per time at fixed depth. In(e), the seasonal cycle at depth x lags the surface by λx/ω days, while amplitude decays by e^{-λx}.')],same(r'\[k=\frac{\omega}{2\lambda^2},\qquad\text{time lag}=\frac{\lambda x}{\omega}.\]'),['a','b','c','d','e'])
add(91,('운동에너지 항등식','Kinetic-energy identity'),('함수 '+r'\(K=\tfrac12mv^2\)'+'에 대해 '+r'\(K_mK_{vv}=K\)'+'를 보이라.','For '+r'\(K=\tfrac12mv^2\)'+' prove '+r'\(K_mK_{vv}=K\)'+'.'),fs(r'K_m=v^2/2,\quad K_v=mv,\quad K_{vv}=m'),same(r'\[K_mK_{vv}=\tfrac12mv^2=K.\]'))
Em=2.65*.66*400**(-.34)+3.5*.75*400**(-.25)/8;Ev=-3.5*400**.75/64
add(92,('이동 에너지의 민감도','Sensitivity of locomotion energy'),('도마뱀의1km 이동에너지모형 '+r'\(E(m,v)=2.65m^{0.66}+3.5m^{0.75}/v\)'+'(kcal, m은g,v는km/h)에서 E_m(400,8),E_v(400,8)을 구하고 해석하라.','For lizard energy per1km '+r'\(E(m,v)=2.65m^{0.66}+3.5m^{0.75}/v\)'+' (kcal, mass ing, speed inkm/h), evaluate and interpret E_m(400,8), E_v(400,8).'),fs(r'E_m=1.749m^{-0.34}+2.625m^{-0.25}/v,\quad E_v=-3.5m^{0.75}/v^2')+[('각 편미분은 속도를 고정한 질량1g당 변화와 질량을 고정한 속도1km/h당 변화를 나타낸다.','They measure changes per gram at fixed speed and per km/h at fixed mass.')],(f'E_m≈{Em:.5f}kcal/g, E_v≈{Ev:.5f}kcal/(km/h). 질량이 증가하면 에너지가 늘고 이 모형에서 속도가 증가하면1km당 에너지가 줄어든다.',f'E_m≈{Em:.5f}kcal/g, E_v≈{Ev:.5f}kcal/(km/h). Greater mass raises energy; greater speed lowers energy per1km in this model.'))
add(93,('타원 교선의 접선','Tangent to an elliptical intersection'),('타원면 '+r'\(4x^2+2y^2+z^2=16\)'+'과 y=2의 교선에서 (1,2,2)를 지나는 접선의 매개식을 구하라.','Find the tangent line at(1,2,2) to the intersection of '+r'\(4x^2+2y^2+z^2=16\)'+' and y=2.'),fs(r'4x^2+z^2=8,\quad8x+2z\frac{dz}{dx}=0',r'\left.\frac{dz}{dx}\right|_{(1,2)}=-2'),same(r'\[x=1+t,\quad y=2,\quad z=2-2t.\]'))
add(94,('포물선 교선의 접선','Tangent to a parabolic intersection'),('포물면 '+r'\(z=6-x-x^2-2y^2\)'+'과 x=1의 교선에서 (1,2,-4)의 접선 매개식을 구하고 세 대상을 같은 화면에 그려라.','Find the tangent at(1,2,-4) to the intersection of '+r'\(z=6-x-x^2-2y^2\)'+' and x=1, and graph the surface, parabola, and tangent together.'),fs(r'x=1:\ z=4-2y^2,\quad dz/dy=-4y',r'\mathbf r(y)=(1,y,4-2y^2),\quad\mathbf r\prime(2)=(0,1,-8)'),same(r'\[x=1,\quad y=2+t,\quad z=-4-8t.\]'))
add(95,('양립할 수 없는 편도함수','Incompatible partial derivatives'),('함수의 편도함수가 '+r'\(f_x=x+4y,\quad f_y=3x-y\)'+'라는 주장을 믿을 수 있는가?','Can a function have '+r'\(f_x=x+4y,\quad f_y=3x-y\)'+' as its partial derivatives?'),fs(r'f_{xy}=4,\quad f_{yx}=3')+[('두 혼합미분이 모두 연속인 다항식인데 값이 다르므로 클레로 정리에 모순이다.','Both mixed partials would be continuous polynomials yet unequal, contradicting Clairaut’s theorem.')],('아니다. 이러한 편도함수를 동시에 갖는 함수는 없다.','No function can have both of these partial derivatives.'))
add(96,('삼각형 각의 편미분','Partials of a triangle angle'),('삼각형의 변 a,b,c와 맞은편 각 A,B,C에 대해 코사인법칙을 음미분하여 '+r'\(A_a,A_b,A_c\)'+'를 구하라.','For triangle sides a,b,c opposite A,B,C, implicitly differentiate the cosine law to find '+r'\(A_a,A_b,A_c\)'+'.'),fs(r'a^2=b^2+c^2-2bc\cos A',r'2a=2bc\sin A\,A_a',r'0=2b-2c\cos A+2bc\sin A\,A_b',r'0=2c-2b\cos A+2bc\sin A\,A_c'),same(r'\[A_a=\frac a{bc\sin A},\quad A_b=\frac{c\cos A-b}{bc\sin A},\quad A_c=\frac{b\cos A-c}{bc\sin A}.\]'))
add(97,('3계 혼합미분의 순서 교환','Interchanging third partials'),('3계 편도함수가 연속일 때 클레로 정리로 '+r'\(f_{xyy}=f_{yxy}=f_{yyx}\)'+'를 보이라.','Use Clairaut’s theorem to prove '+r'\(f_{xyy}=f_{yxy}=f_{yyx}\)'+' when third partials are continuous.'),fs(r'f_{xy}=f_{yx}\implies\partial_yf_{xy}=\partial_yf_{yx}\implies f_{xyy}=f_{yxy}')+[('함수 f_y에 클레로 정리를 적용하면 (f_y)_{xy}=(f_y)_{yx}, 즉 f_{yxy}=f_{yyx}이다.','Apply Clairaut to f_y: (f_y)_{xy}=(f_y)_{yx}, giving f_{yxy}=f_{yyx}.')],same(r'\[f_{xyy}=f_{yxy}=f_{yyx}.\]'))
add(98,('고계 편미분의 개수','Counting higher partial derivatives'),('(a) 두 변수함수의 n계 편미분은 순서까지 구별하면 몇 개인가? (b) 모두 연속이면 서로 다른 것은 최대 몇 개인가? (c) 세 변수에서(a)에 답하라.','(a) Count ordered nth partials of a two-variable function; (b) if they are all continuous, how many can be distinct? (c) answer(a) for three variables.'),[('(a) 매번 두 변수 중 하나를 선택하므로2^n가지이다. (b) 순서가 무관해지고 x미분 횟수0,1,…,n만 구별한다.','(a) There are two choices at each step, giving2^n. (b) Order no longer matters; only the number0,1,…,n of x-derivatives distinguishes them.'),('(c) 매번 세 선택이므로3^n가지이다.','(c) Three choices at each step give3^n.')],same(r'\[(a)\ 2^n;\qquad(b)\ n+1;\qquad(c)\ 3^n.\]'),['a','b','c'])
add(99,('한 단면만 사용한 미분','Differentiating only the needed trace'),('함수 '+r'\(f=x(x^2+y^2)^{-3/2}e^{\sin(x^2y)}\)'+'에서 '+r'\(f_x(1,0)\)'+'을 구하라.','Find '+r'\(f_x(1,0)\)'+' for '+r'\(f=x(x^2+y^2)^{-3/2}e^{\sin(x^2y)}\)'+'.'),[('y=0으로 먼저 고정하고 x=1의 근방 x>0에서 단순화한다.','Fix y=0 first and simplify for x>0 near1.')]+fs(r'f(x,0)=x(x^2)^{-3/2}=x^{-2},\quad\frac d{dx}f(x,0)=-2x^{-3}'),same(r'\[f_x(1,0)=-2.\]'))
# Match statement formula order across languages for99.
b.E[99]['statement']['en']='For '+r'\(f=x(x^2+y^2)^{-3/2}e^{\sin(x^2y)}\)'+' find '+r'\(f_x(1,0)\)'+'.'
add(100,('원점에서 정의로 편미분','Partial at the origin from its definition'),('함수 '+r'\(f=\sqrt[3]{x^3+y^3}\)'+'의 '+r'\(f_x(0,0)\)'+'을 구하라.','Find '+r'\(f=\sqrt[3]{x^3+y^3}\)'+' and its partial '+r'\(f_x(0,0)\)'+'.'),fs(r'f(h,0)=\sqrt[3]{h^3}=h',r'f_x(0,0)=\lim_{h\to0}\frac{h-0}{h}=1'),same(r'\[f_x(0,0)=1.\]'),check=('일반형 도함수 공식에0을 대입하는 대신 실수 세제곱근의 성질을 사용한다.','Use the real cube-root identity rather than substituting zero into a singular general derivative formula.'))
F=(x**3*y-x*y**3)/(x*x+y*y);Fx=s.factor(s.diff(F,x));Fy=s.factor(s.diff(F,y));Fxy=s.factor(s.diff(F,x,y))
add(101,('클레로 정리의 연속성 가정','Why Clairaut needs continuity'),('함수 '+r'\(f=(x^3y-xy^3)/(x^2+y^2)\)'+'를 원점 밖에서, f(0,0)=0으로 정의한다. (a) f를 그리고 (b) 원점 밖의 f_x,f_y, (c) 원점의 두1계 편미분, (d) f_xy(0,0)=-1,f_yx(0,0)=1을 구하라. (e) 두 혼합미분 그래프를 사용해 클레로 정리와 모순인지 설명하라.','Define '+r'\(f=(x^3y-xy^3)/(x^2+y^2)\)'+' off the origin and f(0,0)=0. (a) Graph f; (b) compute f_x,f_y off the origin; (c) compute the first partials at the origin; (d) show f_xy(0,0)=-1,f_yx(0,0)=1; (e) graph the mixed partials and discuss Clairaut’s theorem.'),fs(r'(b)\ f_x='+tex(Fx)+r',\quad f_y='+tex(Fy),r'(c)\ f(h,0)=f(0,h)=0\implies f_x(0,0)=f_y(0,0)=0',r'(d)\ f_x(0,y)=-y,\quad f_y(x,0)=x\implies f_{xy}(0,0)=-1,\ f_{yx}(0,0)=1',r'(e)\ f_{xy}=f_{yx}='+tex(Fxy)+r'\quad((x,y)\ne0)')+[('원점 밖의 혼합미분은 y=0에서1,x=0에서-1이어서 원점 극한이 없다. 따라서 연속성 가정이 실패하며 클레로 정리와 모순되지 않는다.','Off the origin, the common mixed partial equals1 on y=0 and-1 on x=0, so no origin limit exists. The continuity hypothesis fails; there is no contradiction.')],('(b) 표시한 도함수. (c) 둘 다0. (d) -1과1. (e) 연속성 가정이 없어 모순이 아니다.','(b) The displayed derivatives. (c) Both0. (d) -1 and1. (e) No contradiction because continuity fails.'),['a','b','c','d','e'])
assert sorted(b.E)==list(range(1,102));b.save();print('14.3:101 complete; graph additions follow')
